/** Linux directory hierarchy (FHS 3.0 + systemd/usr-merge conventions). */

export interface FsNode {
  name: string;
  summary: string;
  detail?: string;
  /** Virtual filesystem (content generated by the kernel, not stored on disk). */
  virtual?: boolean;
  /** Symbolic link (usr-merge). */
  link?: string;
  security?: string;
  command?: string;
  children?: FsNode[];
}

